def is_complex_pair(x, y):
    import math
    g = math.gcd(x, y)

    # Check if g is not square-free
    def is_square_free(n):
        if n <= 0: return True
        d = 2
        temp = n
        while d * d <= temp:
            if temp % (d * d) == 0:
                return False
            while temp % d == 0:
                temp //= d
            d += 1
        return True

    if not is_square_free(g):
        return True

    if x > 1 and y % (x * x) == 0:
        return True

    if y > 1 and x % (y * y) == 0:
        return True

    return False

