def get_good_set_elements(x, y, limit=500):
    elements = {x, y}
    queue = [x, y]
    while queue:
        a = queue.pop(0)
        for b in elements:
            for i in range(-2, 3): # Try a few i values
                val = a**2 + i*a*b + b**2
                if val not in elements and abs(val) <= limit:
                    elements.add(val)
                    queue.append(val)
    return elements

