def get_good_set_elements(x, y, limit=500):
    elements = {x, y}
    queue = [x, y]
    idx = 0
    while idx < len(queue):
        a = queue[idx]
        idx += 1
        current_elements = list(elements)
        for b in current_elements:
            for i in range(-2, 3):
                val = a**2 + i*a*b + b**2
                if val not in elements and abs(val) <= limit:
                    elements.add(val)
                    queue.append(val)
    return elements

